using System.Text.Json;
using BotZone.Contracts;
using BotZone.Infrastructure.Services;
using Microsoft.Extensions.Configuration;
namespace BotZone.Infrastructure.Seeding;
public sealed class CatalogueSeeder(SqlStore sql,LandingService landing)
{
 public async Task SeedAsync(){var root=Environment.GetEnvironmentVariable("BOTZONE_ROOT")??Directory.GetCurrentDirectory();using var document=JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(root,"data/catalogue-demo.json")));var products=document.RootElement.EnumerateArray().ToArray();var owner=new Actor(DemoSeeder.OwnerId,"Chủ cửa hàng BotZone","owner@botzone.local","owner",true);await sql.Transaction<object>(owner,async()=>{
  if(await sql.Optional("SELECT key FROM app_settings WHERE key='seed:v1.1:catalogue-full'") is not null)return new{already=true};
  var warehouse=(await sql.One("SELECT id FROM warehouses WHERE code='MAIN'")).G("id");var supplier=(await sql.One("SELECT id FROM suppliers WHERE code='DEMO-SUPPLIER'")).G("id");var po=Guid.NewGuid();var receipt=Guid.NewGuid();await sql.Exec("INSERT INTO purchase_orders(id,supplier_id,code,status,created_by,approved_by) VALUES($1,$2,'DEMO-CATALOGUE-PO','received',$3,$3)",po,supplier,owner.Id);await sql.Exec("INSERT INTO goods_receipts(id,purchase_order_id,receipt_no,received_by,event_key) VALUES($1,$2,'DEMO-CATALOGUE-GR','demo-warehouse','seed:catalogue-receipt')",receipt,po);
  var slugIds=new Dictionary<string,Guid>();foreach(var p in products){var category=(await sql.One("SELECT id FROM categories WHERE lower(code)=$1",p.Text("category").ToLowerInvariant())).G("id");var old=await sql.Optional("SELECT id FROM products WHERE model_code=$1",p.Text("modelCode"));var pid=old?.G("id")??Guid.NewGuid();slugIds[p.Text("slug")]=pid;if(old is null){await sql.Exec("INSERT INTO products(id,category_id,slug,model_code,source_url,poster,specs) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)",pid,category,p.Text("slug"),p.Text("modelCode"),p.Text("sourceUrl"),p.Text("poster"),p.Field("specs").GetRawText());foreach(var locale in new[]{"vi","en"})await sql.Exec("INSERT INTO product_translations(product_id,locale,name,description,seo_title) VALUES($1,$2,$3,$4,$5)",pid,locale,p.Text("name"),locale=="vi"?"Sản phẩm Apple mới. Giá bán và gói BotZone Care là cấu hình mô phỏng cho đồ án; xem nguồn thông số của hãng.":"New Apple product. Prices and BotZone Care are simulated coursework settings; see the manufacturer specification source.",p.Text("name")+" | BotZone");}
   foreach(var v in p.Array("variants")){if(await sql.Optional("SELECT id FROM product_variants WHERE sku=$1",v.Text("sku")) is not null)continue;var vid=Guid.NewGuid();await sql.Exec("INSERT INTO product_variants(id,product_id,sku,option_signature,options,price_vnd,tracking_mode,standard_warranty_months,care_fee_vnd) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7,$8,$9)",vid,pid,v.Text("sku"),v.Field("options").GetRawText(),v.Field("options").GetRawText(),v.Money("priceVnd"),v.Text("trackingMode"),v.Int("standardWarrantyMonths"),v.TryGetProperty("careFeeVnd",out var care)&&care.ValueKind!=JsonValueKind.Null?v.Money("careFeeVnd"):null);int quantity=v.Int("stockQuantity");if(quantity<=0)continue;long cost=v.Money("priceVnd")/2;var pi=Guid.NewGuid();var ri=Guid.NewGuid();var lot=Guid.NewGuid();await sql.Exec("INSERT INTO purchase_order_items(id,purchase_order_id,variant_id,quantity,unit_cost_vnd) VALUES($1,$2,$3,$4,$5)",pi,po,vid,quantity,cost);await sql.Exec("INSERT INTO goods_receipt_items(id,receipt_id,purchase_order_id,purchase_order_item_id,received_qty,unit_cost_vnd) VALUES($1,$2,$3,$4,$5,$6)",ri,receipt,po,pi,quantity,cost);await sql.Exec("INSERT INTO inventory_lots(id,warehouse_id,variant_id,receipt_item_id,unit_cost_vnd,qty_on_hand) VALUES($1,$2,$3,$4,$5,$6)",lot,warehouse,vid,ri,cost,quantity);if(v.Text("trackingMode")=="serialized")for(int i=1;i<=quantity;i++){var unit=Guid.NewGuid();await sql.Exec("INSERT INTO inventory_units(id,lot_id) VALUES($1,$2)",unit,lot);await sql.Exec("INSERT INTO inventory_identifiers(inventory_unit_id,kind,normalized_value) VALUES($1,'serial',$2)",unit,$"000BZ-{v.Text("sku")}-{i:0000}");}await sql.Exec("INSERT INTO stock_movements(variant_id,lot_id,quantity_delta,kind,source_event_key,actor_user_id,reason) VALUES($1,$2,$3,'receive',$4,'demo-warehouse','Nhập dữ liệu catalogue demo có nguồn phiếu nhập')",vid,lot,quantity,"catalogue-receive:"+vid);}
  }
  foreach(var p in products)if(p.TryGetProperty("compatibleSlugs",out var compatible))foreach(var slug in compatible.EnumerateArray())if(slugIds.TryGetValue(slug.GetString()!,out var target))await sql.Exec("INSERT INTO product_compatibilities(accessory_product_id,target_product_id) VALUES($1,$2) ON CONFLICT DO NOTHING",slugIds[p.Text("slug")],target);
  await sql.Exec("INSERT INTO app_settings(key,value) VALUES('seed:v1.1:catalogue-full',$1::jsonb)",Values.Json(new{productCount=products.Length,source="data/catalogue-demo.json",appliedAt=DateTime.UtcNow}));return new{seeded=products.Length};
 });
 var content=new Actor("demo-content","Biên tập viên","content@botzone.local","content_staff",true);await sql.Transaction<object>(content,async()=>{var page=await sql.Optional("SELECT id FROM landing_pages WHERE slug='home'");if(page is null)page=await sql.One("INSERT INTO landing_pages(slug) VALUES('home') RETURNING id");var id=page.G("id");if(await sql.Optional("SELECT page_id FROM landing_drafts WHERE page_id=$1",id) is not null)return new{preserved=true};var sections=new[]{new{id="hero-pro-max",type="hero",title=new{vi="Sắc Burgundy. Dấu ấn của bạn.",en="Burgundy. Make it yours."},subtitle=new{vi="Khám phá iPhone 18 Pro Max — giá bán mô phỏng tại BotZone.",en="Explore iPhone 18 Pro Max — simulated prices at BotZone."},productSlug="iphone-18-pro-max",poster="/media/phone-burgundy.svg",model="procedural:phone",colors=new[]{"#4B1527","#C6DBE3","#222222"},preset="float",camera=5,tilt=8,light=2,speed=1,fold=0},new{id="duo-story",type="duo",title=new{vi="Mở ra một góc nhìn mới.",en="Unfold a new perspective."},subtitle=new{vi="iPhone Duo. Khám phá chuyển động mở và gập.",en="iPhone Duo. Explore the unfolding motion."},productSlug="iphone-duo",poster="/media/duo.svg",model="procedural:duo",colors=new[]{"#202B34","#F2F0E9"},preset="fold",camera=5,tilt=6,light=2,speed=1,fold=90}};await sql.Exec("INSERT INTO landing_drafts(page_id,revision,sections,updated_by) VALUES($1,0,$2::jsonb,$3)",id,File.Exists(Path.Combine(root,"data/landing-demo.json"))?await File.ReadAllTextAsync(Path.Combine(root,"data/landing-demo.json")):Values.Json(sections),content.Id);await landing.Handle(content,"publish_landing",JsonSerializer.SerializeToElement(new{revision=0}),"seed:landing-initial");return new{published=true};});
 }
}
